INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind alle PCIe-Steckplätze gleich groß?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Längen wie x16, x8"}, {"text": "Ja", "correct": false, "because": "Größen variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptzweck dieser Erweiterungsslots?', 3, '[{"text": "Anschluss von Zusatzhardware", "correct": true, "because": "Ermöglicht Grafikkarten oder SSDs"}, {"text": "Speichererweiterung", "correct": false, "because": "RAM nutzt andere Slots"}, {"text": "Manuelle Kühlung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte nutzen typischerweise diese Slots?', 5, '[{"text": "Grafikkarten", "correct": true, "because": "Hohe Bandbreite nötig"}, {"text": "NVMe-SSDs", "correct": true, "because": "Nutzen PCIe für Schnelligkeit"}, {"text": "Tastaturen", "correct": false, "because": "Nutzen USB"}, {"text": "Monitore", "correct": false, "because": "Andere Anschlüsse"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PCIe x16 bietet die höchste Bandbreite. b) Alle Slots sind für jede Karte geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Kompatibilität ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Erweiterungsslots?', 4, '[{"text": "Lane-Anzahl", "correct": false, "because": "Bestimmt Bandbreite"}, {"text": "PCIe-Version", "correct": false, "because": "Beeinflusst Geschwindigkeit"}, {"text": "Gehäusefarbe", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein x16-Slot auch x1-Karten unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "Abwärtskompatibel"}, {"text": "Nein", "correct": false, "because": "Größere Slots akzeptieren kleinere"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt PCIe einen parallelen Bus?', 3, '[{"text": "Nein", "correct": true, "because": "Serieller Punkt-zu-Punkt"}, {"text": "Ja", "correct": false, "because": "Anders als älterer PCI"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren bestimmen die Leistung eines Slots?', 5, '[{"text": "Lane-Anzahl", "correct": true, "because": "Mehr Lanes, mehr Bandbreite"}, {"text": "PCIe-Version", "correct": true, "because": "Neuere Versionen sind schneller"}, {"text": "Slot-Farbe", "correct": false, "because": "Kein Leistungsfaktor"}, {"text": "Mainboardgröße", "correct": false, "because": "Nur indirekt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) PCIe 5.0 ist doppelt so schnell wie 4.0. b) Alle Mainboards haben x16-Slots. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist bei Mini-Boards falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Nutzung eines PCIe-Steckplatzes?', 4, '[{"text": "Kompatible Karte", "correct": false, "because": "Erforderlich für Funktion"}, {"text": "Treiber", "correct": false, "because": "Oft nötig für Geräte"}, {"text": "Externe Stromquelle", "correct": true, "because": "Slot liefert Strom"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PCIe-Steckplätze für RAM genutzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "RAM nutzt DIMM-Slots"}, {"text": "Ja", "correct": false, "because": "Andere Schnittstelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche PCIe-Version ist für Gaming-Grafikkarten entscheidend?', 4, '[{"text": "Neueste verfügbare", "correct": true, "because": "Maximiert Bandbreite"}, {"text": "Älteste Version", "correct": false, "because": "Bietet weniger Leistung"}, {"text": "Mittlere Version", "correct": false, "because": "Nicht optimal"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass PCIe-Steckplätze nur für Grafikkarten sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für SSDs, Netzwerkkarten"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines Slots für eine Grafikkarte?', 3, '[{"text": "Hohe Lane-Anzahl", "correct": true, "because": "Sichert maximale Bandbreite"}, {"text": "Kleine Slotgröße", "correct": false, "because": "Einschränkt Leistung"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Automatisch geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PCIe x4 passt in x16-Slots. b) PCIe ersetzt USB.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist eine andere Schnittstelle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten moderne PCIe-Steckplätze?', 5, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Schnelle Datenübertragung"}, {"text": "Abwärtskompatibilität", "correct": true, "because": "Ältere Karten nutzbar"}, {"text": "Geringe Latenz", "correct": false, "because": "Latenz hardwareabhängig"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisch geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung eines PCIe-Steckplatzes unwichtig?', 3, '[{"text": "Kompatibilität", "correct": false, "because": "Sichert Funktion"}, {"text": "Stromversorgung", "correct": false, "because": "Wird bereitgestellt"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verdoppelt PCIe 5.0 die Bandbreite von 4.0?', 3, '[{"text": "Ja", "correct": true, "because": "Pro Lane doppelte Datenrate"}, {"text": "Nein", "correct": false, "because": "Verdopplung ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PCIe-Steckplätze für Audio geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Soundkarten nutzen PCIe"}, {"text": "Nein", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Nutzung eines PCIe-Steckplatzes?', 4, '[{"text": "Einbau einer High-End-Grafikkarte", "correct": true, "because": "Nutzt x16 für Bandbreite"}, {"text": "Anschluss eines Druckers", "correct": false, "because": "Nutzt USB"}, {"text": "Installation von RAM", "correct": false, "because": "Andere Slots"}]');
